INSERT INTO engine_schemas (rowid, namespace, name, version, document, hash, defined_at, published_at, defined_by, published_by, published_cursor) VALUES (1, 'default', 'documents', 1, '{"description":"A document an engine runs with the core''s behaviors and no extension: it moves from draft through review to published, collects comments, and keeps its revisions, and a change to it can be proposed for a reviewer to approve.","kind":"General","name":"documents","types":{"Document":{"behaviors":[{"config":{"states":["draft","review","published","archived"],"transitions":[{"from":"draft","to":"review"},{"from":"review","to":"draft"},{"from":"review","permission":"documents.publish","to":"published"},{"from":"published","to":"archived"}]},"name":"Workflow"},{"name":"Comments"},{"config":{"review":{"permission":"documents.review"}},"name":"Revisions"}],"fields":[{"name":"title","required":true,"typeRef":{"name":"string"},"validateMaxLength":200},{"name":"body","typeRef":{"name":"string"}}],"name":"Document","role":"EmbeddedStruct"}}}', '478cd2cdc701a0989897fdf19dbd823e704d5fde48c6ce9e0c60f946d956563b', 1791536400000, 1791536400000, 'alice', 'alice', 2);
INSERT INTO engine_schemas (rowid, namespace, name, version, document, hash, defined_at, published_at, defined_by, published_by, published_cursor) VALUES (2, 'default', 'tasks', 1, '{"description":"A task an engine runs with the core''s behaviors and no extension: it moves from todo through doing to done, waits for its blockers, a task or a document, before it is done, and links to the document it implements, pinned to a revision, to a parent task and to its project, which every create gives.","kind":"General","name":"tasks","types":{"Task":{"behaviors":[{"config":{"states":["todo","doing","done","dropped"],"transitions":[{"from":"todo","to":"doing"},{"from":"doing","to":"done"},{"from":"todo","to":"dropped"},{"from":"doing","to":"dropped"}]},"name":"Workflow"},{"config":{"gatedStates":["done"],"schemas":["tasks","documents"]},"name":"Dependencies"},{"config":{"links":{"parent":{"schema":"tasks"},"project":{"required":true,"schema":"projects"},"spec":{"pinned":true,"schema":"documents"}}},"name":"Links"}],"fields":[{"name":"title","required":true,"typeRef":{"name":"string"},"validateMaxLength":200}],"name":"Task","role":"EmbeddedStruct"}}}', '88b49e1bb9dd9a410d173f997551da6295d3fcc54c4e182df558f2d7e96282f6', 1791536400000, 1791536400000, 'alice', 'alice', 4);
INSERT INTO engine_schemas (rowid, namespace, name, version, document, hash, defined_at, published_at, defined_by, published_by, published_cursor) VALUES (3, 'default', 'projects', 1, '{"description":"A project an engine runs with the core''s behaviors and no extension: it moves from active to done or dropped, and rolls up the tasks that point at it through their project link: how many there are, how many are in each status, and whether every one is in a terminal state, which it needs before it is done.","kind":"General","name":"projects","types":{"Project":{"behaviors":[{"config":{"states":["active","done","dropped"],"transitions":[{"from":"active","to":"done"},{"from":"active","to":"dropped"}]},"name":"Workflow"},{"config":{"rollups":{"tasks":{"function":"count","link":"project","schema":"tasks"},"tasksByStatus":{"field":"Workflow.status","function":"countBy","link":"project","schema":"tasks"},"tasksFinished":{"function":"all","gatedStates":["done"],"link":"project","schema":"tasks"}}},"name":"Rollups"}],"fields":[{"name":"title","required":true,"typeRef":{"name":"string"},"validateMaxLength":200}],"name":"Project","role":"EmbeddedStruct"}}}', 'afe736ff5af973fc5731eedf68d40082259e6638b8a5141afce662a6886637db', 1791536400000, 1791536400000, 'alice', 'alice', 6);
INSERT INTO engine_schemas (rowid, namespace, name, version, document, hash, defined_at, published_at, defined_by, published_by, published_cursor) VALUES (4, 'default', 'notes', 1, '{"description":"A note an engine runs with the core''s Search and no extension: its title and body are indexed, the title weighing three times the body, and an embedder settles a vector of 384 numbers for each.","kind":"General","name":"notes","types":{"Note":{"behaviors":[{"config":{"fields":["title","body"],"vectors":{"dimensions":384,"model":"minilm-l6","permission":"notes.embed"},"weights":{"title":3}},"name":"Search"}],"fields":[{"name":"title","required":true,"typeRef":{"name":"string"},"validateMaxLength":200},{"name":"body","typeRef":{"name":"string"}}],"name":"Note","role":"EmbeddedStruct"}}}', '6d7a5f4c4b94a4679d51b34045ea9338c61d24d647f2bf2b965dbba2d200bd7b', 1791536400000, 1791536400000, 'alice', 'alice', 8);
INSERT INTO engine_schemas (rowid, namespace, name, version, document, hash, defined_at, published_at, defined_by, published_by, published_cursor) VALUES (5, 'default', 'Step', 1, '{"description":"A step an engine runs with the core''s Constants and Variants and no extension: its kind is set at create and never changes, and its result has the shape its kind gives it, a VerifyResult for a verify step and a ReviewResult for a review, and none for a note.","enums":{"StepKind":{"name":"StepKind","values":[{"name":"Verify","serializedAs":"verify"},{"name":"Review","serializedAs":"review"},{"name":"Note","serializedAs":"note"}]}},"kind":"General","name":"Step","scalars":{"Generic.JSON":{"languagePrimitive":"object","name":"Generic.JSON"}},"types":{"Check":{"fields":[{"name":"name","required":true,"typeRef":{"name":"string"}},{"name":"ok","required":true,"typeRef":{"name":"boolean"}}],"name":"Check","role":"EmbeddedStruct"},"ReviewResult":{"fields":[{"name":"approved","required":true,"typeRef":{"name":"boolean"}},{"name":"notes","typeRef":{"name":"string"}}],"name":"ReviewResult","role":"EmbeddedStruct"},"Step":{"behaviors":[{"config":{"fields":["kind"]},"name":"Constants"},{"config":{"by":"kind","field":"result","types":{"review":"ReviewResult","verify":"VerifyResult"}},"name":"Variants"}],"fields":[{"name":"title","required":true,"typeRef":{"name":"string"}},{"name":"kind","required":true,"typeRef":{"name":"StepKind"}},{"name":"result","typeRef":{"name":"Generic.JSON"}}],"name":"Step","role":"EmbeddedStruct"},"VerifyResult":{"fields":[{"name":"passed","required":true,"typeRef":{"name":"boolean"}},{"name":"checks","typeRef":{"isArray":true,"name":"Check"}}],"name":"VerifyResult","role":"EmbeddedStruct"}}}', '806c40ede915ceff5eb1e062f9f7bfe9b8abb902925881f0377423d042077362', 1791536400000, 1791536400000, 'alice', 'alice', 10);
INSERT INTO engine_schemas (rowid, namespace, name, version, document, hash, defined_at, published_at, defined_by, published_by, published_cursor) VALUES (6, 'default', 'Recipe', 1, '{"description":"A recipe an engine versions with the core''s Branches and no extension: each recipe is the root of a version graph whose steps are ordered by position, whose ingredients belong to a step, and which has at most one cover. Work happens on drafts, which merge into the recipe''s primary line, and a tagged commit of it is released.","kind":"General","name":"Recipe","scalars":{"Generic.Int64":{"languagePrimitive":"number","name":"Generic.Int64"},"Generic.JSON":{"languagePrimitive":"object","name":"Generic.JSON"},"Identity.UUID":{"languagePrimitive":"string","name":"Identity.UUID"}},"types":{"Cover":{"fields":[{"name":"photoUrl","required":true,"typeRef":{"name":"string"}}],"name":"Cover","role":"EmbeddedStruct"},"Ingredient":{"fields":[{"name":"stepKey","required":true,"typeRef":{"name":"Identity.UUID"}},{"name":"quantity","required":true,"typeRef":{"name":"string"}}],"name":"Ingredient","role":"EmbeddedStruct"},"Recipe":{"behaviors":[{"config":{"kinds":{"cover":{"singleton":true,"type":"Cover"},"ingredient":{"parent":{"key":"stepKey","of":"step"},"type":"Ingredient"},"step":{"order":"position","retentionDays":365,"type":"Step","units":{"timings":"keyed"}}},"sweep":{"abandonAfter":2592000000,"intervalMs":3600000}},"name":"Branches"}],"fields":[{"name":"title","required":true,"typeRef":{"name":"string"}}],"name":"Recipe","role":"EmbeddedStruct"},"Step":{"fields":[{"name":"instruction","required":true,"typeRef":{"name":"string"}},{"name":"position","required":true,"typeRef":{"name":"Generic.Int64"}},{"name":"timings","typeRef":{"name":"Generic.JSON"}}],"name":"Step","role":"EmbeddedStruct"}}}', '9b99c85165aeb70abf7b8f1a4eb977dc1e79f7c5eadf4d56ee04a0987f6af313', 1791536400000, 1791536400000, 'alice', 'alice', 12);
INSERT INTO engine_schemas (rowid, namespace, name, version, document, hash, defined_at, published_at, defined_by, published_by, published_cursor) VALUES (7, 'default', 'invoices', 1, '{"description":"An invoice an engine runs with the core''s Workflow and StateRules and no extension: it is drafted with any fields, sent only with a customer, an amount and its lines, which then stay as they are, and paid or voided with no field left to change but by a caller who may amend it.","kind":"General","name":"invoices","scalars":{"Generic.Int64":{"languagePrimitive":"number","name":"Generic.Int64"}},"types":{"Invoice":{"behaviors":[{"config":{"outcomes":{"void":"neutral"},"states":["draft","sent","paid","void"],"transitions":[{"from":"draft","to":"sent"},{"from":"sent","to":"draft"},{"from":"sent","to":"paid"},{"from":"draft","to":"void"},{"from":"sent","to":"void"}]},"name":"Workflow"},{"config":{"permission":"invoices.amend","states":{"paid":{"frozen":"all"},"sent":{"frozen":["customer","amount","lines"],"required":["customer","amount","lines"]},"void":{"frozen":"all"}}},"name":"StateRules"}],"fields":[{"name":"title","required":true,"typeRef":{"name":"string"},"validateMaxLength":200},{"name":"customer","typeRef":{"name":"string"}},{"name":"amount","typeRef":{"name":"Generic.Int64"}},{"name":"lines","typeRef":{"isArray":true,"name":"string"}},{"name":"notes","typeRef":{"name":"string"}}],"name":"Invoice","role":"EmbeddedStruct"}}}', '8738abcd5cc2f7a7cdb2c90b10e0ef70d3073438457153f715a34f1dbeb8809b', 1791536400000, 1791536400000, 'alice', 'alice', 14);
INSERT INTO engine_schemas (rowid, namespace, name, version, document, hash, defined_at, published_at, defined_by, published_by, published_cursor) VALUES (8, 'default', 'expenses', 1, '{"description":"An expense claim an engine runs with the core''s behaviors and no extension: it moves from draft to submitted, and on to approved, which waits for two sign-offs by principals with expenses.approve, the claimant''s never among them, then to paid, which waits for one with expenses.pay. A change of the claim consumes the sign-offs it has, and entering approved or paid consumes that gate''s.","kind":"General","name":"expenses","types":{"Expense":{"behaviors":[{"config":{"states":["draft","submitted","approved","paid","rejected"],"transitions":[{"from":"draft","to":"submitted"},{"from":"submitted","to":"draft"},{"from":"submitted","to":"approved"},{"from":"submitted","to":"rejected"},{"from":"approved","to":"paid"}]},"name":"Workflow"},{"config":{"gates":{"approved":{"count":2,"permission":"expenses.approve"},"paid":{"count":1,"from":["approved"],"permission":"expenses.pay"}}},"name":"Approvals"}],"fields":[{"name":"title","required":true,"typeRef":{"name":"string"},"validateMaxLength":200},{"name":"amount","required":true,"typeRef":{"name":"number"},"validateMin":0}],"name":"Expense","role":"EmbeddedStruct"}}}', '4c30281e903c27fa19ef14acb7c3b6a18dfca5057d30fb5c2037eac3b8757bb8', 1791536400000, 1791536400000, 'alice', 'alice', 16);
INSERT INTO engine_schemas (rowid, namespace, name, version, document, hash, defined_at, published_at, defined_by, published_by, published_cursor) VALUES (9, 'default', 'requests', 1, '{"description":"A support request an engine runs with the core''s Workflow and Timers and no extension: one open four hours without an answer is escalated, one waiting a week on its customer is resolved, and a visit is reminded a day before its time. Leaving open or waiting cancels its deadline, and a principal with requests.timers resets or snoozes one.","kind":"General","name":"requests","scalars":{"Temporal.DateTime":{"languagePrimitive":"string","name":"Temporal.DateTime"}},"types":{"Request":{"behaviors":[{"config":{"states":["open","waiting","escalated","resolved"],"transitions":[{"from":"open","to":"waiting"},{"from":"waiting","to":"open"},{"from":"open","to":"escalated"},{"from":"escalated","to":"open"},{"from":"open","to":"resolved"},{"from":"waiting","to":"resolved"},{"from":"escalated","to":"resolved"}]},"name":"Workflow"},{"config":{"deadlines":{"lapse":{"afterMs":604800000,"start":{"enters":"waiting"},"then":{"transition":"resolved"},"until":{"leaves":"waiting"}},"remind":{"afterMs":-86400000,"start":{"field":"visitAt"},"until":{"enters":["resolved"]}},"respond":{"afterMs":14400000,"start":{"enters":"open"},"then":{"transition":"escalated"},"until":{"leaves":"open"}}},"permission":"requests.timers","sweepMs":60000},"name":"Timers"}],"fields":[{"name":"title","required":true,"typeRef":{"name":"string"},"validateMaxLength":200},{"name":"visitAt","typeRef":{"name":"Temporal.DateTime"}}],"name":"Request","role":"EmbeddedStruct"}}}', 'd080b1fa6ea79edd8d46659404b5ba89dc2398ee50614480037c1434bf4860aa', 1791536400000, 1791536400000, 'alice', 'alice', 18);
INSERT INTO engine_schemas (rowid, namespace, name, version, document, hash, defined_at, published_at, defined_by, published_by, published_cursor) VALUES (10, 'default', 'jobs', 1, '{"description":"A job an engine runs with the core''s work-queue behaviors and no extension: a worker claims the queued job of a topic with the highest priority, holds its lease while it runs, and a lease that expires puts the job back in the queue, until its third expiry fails it. A claim reserves CPU seconds from a daily budget, and a failed attempt is retried per failure class until its caps fail the job.","kind":"General","name":"jobs","scalars":{"Generic.Int64":{"languagePrimitive":"number","name":"Generic.Int64"}},"types":{"Job":{"behaviors":[{"config":{"states":["queued","running","done","failed"],"transitions":[{"from":"queued","to":"running"},{"from":"running","to":"queued"},{"from":"running","to":"done"},{"from":"running","to":"failed"},{"from":"queued","to":"failed"}]},"name":"Workflow"},{"config":{"escalate":{"from":["running"],"transition":"failed"},"maxExpiries":3,"maxHoldField":"timeLimitMs","onExpiry":{"from":["running"],"transition":"queued"},"overridePermission":"jobs.override","ttlMs":30000},"name":"Lease"},{"config":{"permission":"jobs.assign"},"name":"Assignment"},{"config":{"claim":{"from":["queued"],"to":"running"},"match":["topic"],"priorityField":"priority"},"name":"Queue"},{"config":{"limitPermission":"jobs.budget","meters":{"cpuSeconds":{"limit":3600,"reserve":600,"reset":"daily"}}},"name":"Budget"},{"config":{"classes":{"invalidOutput":{"attempts":2},"rejected":"terminal","timeout":{"attempts":3}},"exhaustedState":"failed","totalAttempts":4},"name":"Retries"}],"fields":[{"name":"title","required":true,"typeRef":{"name":"string"},"validateMaxLength":200},{"name":"topic","typeRef":{"name":"string"}},{"name":"priority","typeRef":{"name":"Generic.Int64"}},{"name":"timeLimitMs","typeRef":{"name":"Generic.Int64"}}],"name":"Job","role":"EmbeddedStruct"}}}', 'a0e162272c32763952744094f8fbca6dc3f2117215915ae08c08bc48c9be0d3d', 1791536400000, 1791536400000, 'alice', 'alice', 20);
INSERT INTO engine_schemas (rowid, namespace, name, version, document, hash, defined_at, published_at, defined_by, published_by, published_cursor) VALUES (11, 'default', 'workers', 1, '{"kind":"General","name":"workers","types":{"Worker":{"behaviors":[{"config":{"states":["idle","busy","missing","stopped"],"transitions":[{"from":"idle","to":"busy"},{"from":"busy","to":"idle"},{"from":"idle","to":"missing"},{"from":"busy","to":"missing"},{"from":"missing","to":"idle"},{"from":"idle","to":"stopped"},{"from":"busy","to":"stopped"},{"from":"missing","to":"stopped"}]},"name":"Workflow"},{"config":{"onBeat":{"from":["missing"],"transition":"idle"},"onMissed":{"from":["idle","busy"],"transition":"missing"},"principalField":"subject","releaseLeases":["jobs"],"sweepMs":5000,"ttlMs":30000},"name":"Presence"}],"fields":[{"name":"subject","required":true,"typeRef":{"name":"string"}},{"name":"name","typeRef":{"name":"string"}}],"name":"Worker","role":"EmbeddedStruct"}}}', 'c0c9f1ec0856a0f53cecc4552fd5caccea8a4268c4a839ca4599020412fdbcab', 1791536400000, 1791536400000, 'alice', 'alice', 22);
INSERT INTO engine_schemas (rowid, namespace, name, version, document, hash, defined_at, published_at, defined_by, published_by, published_cursor) VALUES (12, 'default', 'steps', 1, '{"kind":"General","name":"steps","types":{"Step":{"behaviors":[{"config":{"states":["queued","running","done"],"transitions":[{"from":"queued","to":"running"},{"from":"running","to":"done"}]},"name":"Workflow"},{"config":{"fields":["step","topic"]},"name":"Constants"},{"name":"Dependencies"},{"config":{"links":{"batch":{"required":true,"schema":"batches"}}},"name":"Links"}],"fields":[{"name":"step","required":true,"typeRef":{"name":"string"}},{"name":"title","typeRef":{"name":"string"}},{"name":"topic","typeRef":{"name":"string"}}],"name":"Step","role":"EmbeddedStruct"}}}', 'eb1f57a112c254d2ec21c937050f97ee81c40cca7cd419059394a64a485b33f1', 1791536400000, 1791536400000, 'alice', 'alice', 24);
INSERT INTO engine_schemas (rowid, namespace, name, version, document, hash, defined_at, published_at, defined_by, published_by, published_cursor) VALUES (13, 'default', 'batches', 1, '{"kind":"General","name":"batches","types":{"Batch":{"behaviors":[{"config":{"copyFields":["topic"],"keyField":"step","parentLink":"batch","schema":"steps","steps":{"check":{"after":["fetch"],"when":{"equals":"search","field":"topic"}},"fetch":{},"index":{"after":["check"],"data":{"title":"Index what was fetched"}}}},"name":"Blueprint"}],"fields":[{"name":"title","required":true,"typeRef":{"name":"string"}},{"name":"topic","typeRef":{"name":"string"}}],"name":"Batch","role":"EmbeddedStruct"}}}', '0b83860613a1aa34cb21a42f0e27541f7ed560f2b4d1078551494fc60f65dcac', 1791536400000, 1791536400000, 'alice', 'alice', 26);
INSERT INTO engine_schemas (rowid, namespace, name, version, document, hash, defined_at, published_at, defined_by, published_by, published_cursor) VALUES (14, 'tree', 'projects', 1, '{"description":"A project an engine runs with the core''s behaviors and no extension: it moves from todo through doing to done, or fails, may be part of a parent project, starts its parent when it starts, is done once every project under it is done, and fails when one of them fails.","kind":"General","name":"projects","types":{"Project":{"behaviors":[{"config":{"outcomes":{"failed":"failure"},"states":["todo","doing","done","failed"],"transitions":[{"from":"todo","to":"doing"},{"from":"doing","to":"done"},{"from":"doing","to":"failed"}]},"name":"Workflow"},{"config":{"links":{"parent":{"schema":"projects"}}},"name":"Links"},{"config":{"rules":[{"then":{"link":"parent","transition":"doing"},"when":{"enters":"doing"}},{"then":{"transition":"done"},"when":{"allTerminal":{"link":"parent","outcomes":["success"],"schema":"projects"}}},{"then":{"transition":"failed"},"when":{"anyTerminal":{"link":"parent","outcomes":["failure"],"schema":"projects"}}}]},"name":"Reactions"}],"fields":[{"name":"title","required":true,"typeRef":{"name":"string"},"validateMaxLength":200}],"name":"Project","role":"EmbeddedStruct"}}}', '6c47a44f495ca9624f2f6431ffee2ce03f2f8517406b9979e4c9210ef1902aab', 1791536400000, 1791536400000, 'alice', 'alice', 28);
INSERT INTO engine_schemas (rowid, namespace, name, version, document, hash, defined_at, published_at, defined_by, published_by, published_cursor) VALUES (15, 'billing', 'documents', 1, '{"description":"A document an engine runs with the core''s behaviors and no extension: it moves from draft through review to published, collects comments, and keeps its revisions, and a change to it can be proposed for a reviewer to approve.","kind":"General","name":"documents","types":{"Document":{"behaviors":[{"config":{"states":["draft","review","published","archived"],"transitions":[{"from":"draft","to":"review"},{"from":"review","to":"draft"},{"from":"review","permission":"documents.publish","to":"published"},{"from":"published","to":"archived"}]},"name":"Workflow"},{"name":"Comments"},{"config":{"review":{"permission":"documents.review"}},"name":"Revisions"}],"fields":[{"name":"title","required":true,"typeRef":{"name":"string"},"validateMaxLength":200},{"name":"body","typeRef":{"name":"string"}}],"name":"Document","role":"EmbeddedStruct"}}}', '478cd2cdc701a0989897fdf19dbd823e704d5fde48c6ce9e0c60f946d956563b', 1791536400000, 1791536400000, 'alice', 'alice', 30);
INSERT INTO engine_schemas (rowid, namespace, name, version, document, hash, defined_at, published_at, defined_by, published_by, published_cursor) VALUES (16, 'billing', 'tasks', 1, '{"description":"A task an engine runs with the core''s behaviors and no extension: it moves from todo through doing to done, waits for its blockers, a task or a document, before it is done, and links to the document it implements, pinned to a revision, to a parent task and to its project, which every create gives.","kind":"General","name":"tasks","types":{"Task":{"behaviors":[{"config":{"states":["todo","doing","done","dropped"],"transitions":[{"from":"todo","to":"doing"},{"from":"doing","to":"done"},{"from":"todo","to":"dropped"},{"from":"doing","to":"dropped"}]},"name":"Workflow"},{"config":{"gatedStates":["done"],"schemas":["tasks","documents"]},"name":"Dependencies"},{"config":{"links":{"parent":{"schema":"tasks"},"project":{"required":true,"schema":"projects"},"spec":{"pinned":true,"schema":"documents"}}},"name":"Links"}],"fields":[{"name":"title","required":true,"typeRef":{"name":"string"},"validateMaxLength":200}],"name":"Task","role":"EmbeddedStruct"}}}', '88b49e1bb9dd9a410d173f997551da6295d3fcc54c4e182df558f2d7e96282f6', 1791536400000, 1791536400000, 'alice', 'alice', 32);
INSERT INTO engine_schemas (rowid, namespace, name, version, document, hash, defined_at, published_at, defined_by, published_by, published_cursor) VALUES (17, 'billing', 'projects', 1, '{"description":"A project an engine runs with the core''s behaviors and no extension: it moves from active to done or dropped, and rolls up the tasks that point at it through their project link: how many there are, how many are in each status, and whether every one is in a terminal state, which it needs before it is done.","kind":"General","name":"projects","types":{"Project":{"behaviors":[{"config":{"states":["active","done","dropped"],"transitions":[{"from":"active","to":"done"},{"from":"active","to":"dropped"}]},"name":"Workflow"},{"config":{"rollups":{"tasks":{"function":"count","link":"project","schema":"tasks"},"tasksByStatus":{"field":"Workflow.status","function":"countBy","link":"project","schema":"tasks"},"tasksFinished":{"function":"all","gatedStates":["done"],"link":"project","schema":"tasks"}}},"name":"Rollups"}],"fields":[{"name":"title","required":true,"typeRef":{"name":"string"},"validateMaxLength":200}],"name":"Project","role":"EmbeddedStruct"}}}', 'afe736ff5af973fc5731eedf68d40082259e6638b8a5141afce662a6886637db', 1791536400000, 1791536400000, 'alice', 'alice', 34);
INSERT INTO engine_schemas (rowid, namespace, name, version, document, hash, defined_at, published_at, defined_by, published_by, published_cursor) VALUES (18, 'billing', 'invoices', 1, '{"description":"An invoice an engine runs with the core''s behaviors and no extension: it bills the project every create gives, and is numbered at its create, INV-2026-0001 on, in a count of its project''s own that starts again each UTC year.","kind":"General","name":"invoices","types":{"Invoice":{"behaviors":[{"config":{"links":{"project":{"required":true,"schema":"projects"}}},"name":"Links"},{"config":{"format":"INV-{yyyy}-{seq:4}","reset":"yearly","scope":{"link":"project"}},"name":"Numbering"}],"fields":[{"name":"title","required":true,"typeRef":{"name":"string"},"validateMaxLength":200},{"name":"amount","typeRef":{"name":"number"}}],"name":"Invoice","role":"EmbeddedStruct"}}}', '31c3cc2505e02ac8254ee76f1cbccf53013b145f6053415ba0d9383236cec10f', 1791536400000, 1791536400000, 'alice', 'alice', 36);
