INSERT INTO engine_events (cursor, kind, namespace, schema, instance_id, seq, version, actor, at, change, cause_behavior, cause_event, cause_schedule, depth, service, value_refs) VALUES (28, 'publish', 'tree', 'projects', NULL, NULL, 1, 'alice', 1791536400000, '{"description":"A project an engine runs with the core''s behaviors and no extension: it moves from todo through doing to done, or fails, may be part of a parent project, starts its parent when it starts, is done once every project under it is done, and fails when one of them fails.","kind":"General","name":"projects","types":{"Project":{"behaviors":[{"config":{"outcomes":{"failed":"failure"},"states":["todo","doing","done","failed"],"transitions":[{"from":"todo","to":"doing"},{"from":"doing","to":"done"},{"from":"doing","to":"failed"}]},"name":"Workflow"},{"config":{"links":{"parent":{"schema":"projects"}}},"name":"Links"},{"config":{"rules":[{"then":{"link":"parent","transition":"doing"},"when":{"enters":"doing"}},{"then":{"transition":"done"},"when":{"allTerminal":{"link":"parent","outcomes":["success"],"schema":"projects"}}},{"then":{"transition":"failed"},"when":{"anyTerminal":{"link":"parent","outcomes":["failure"],"schema":"projects"}}}]},"name":"Reactions"}],"fields":[{"name":"title","required":true,"typeRef":{"name":"string"},"validateMaxLength":200}],"name":"Project","role":"EmbeddedStruct"}}}', NULL, NULL, NULL, 0, NULL, NULL);
INSERT INTO engine_events (cursor, kind, namespace, schema, instance_id, seq, version, actor, at, change, cause_behavior, cause_event, cause_schedule, depth, service, value_refs) VALUES (29, 'define', 'billing', 'documents', NULL, NULL, NULL, 'alice', 1791536400000, '{"hash":"478cd2cdc701a0989897fdf19dbd823e704d5fde48c6ce9e0c60f946d956563b"}', NULL, NULL, NULL, 0, NULL, NULL);
INSERT INTO engine_events (cursor, kind, namespace, schema, instance_id, seq, version, actor, at, change, cause_behavior, cause_event, cause_schedule, depth, service, value_refs) VALUES (30, 'publish', 'billing', 'documents', NULL, NULL, 1, 'alice', 1791536400000, '{"description":"A document an engine runs with the core''s behaviors and no extension: it moves from draft through review to published, collects comments, and keeps its revisions, and a change to it can be proposed for a reviewer to approve.","kind":"General","name":"documents","types":{"Document":{"behaviors":[{"config":{"states":["draft","review","published","archived"],"transitions":[{"from":"draft","to":"review"},{"from":"review","to":"draft"},{"from":"review","permission":"documents.publish","to":"published"},{"from":"published","to":"archived"}]},"name":"Workflow"},{"name":"Comments"},{"config":{"review":{"permission":"documents.review"}},"name":"Revisions"}],"fields":[{"name":"title","required":true,"typeRef":{"name":"string"},"validateMaxLength":200},{"name":"body","typeRef":{"name":"string"}}],"name":"Document","role":"EmbeddedStruct"}}}', NULL, NULL, NULL, 0, NULL, NULL);
INSERT INTO engine_events (cursor, kind, namespace, schema, instance_id, seq, version, actor, at, change, cause_behavior, cause_event, cause_schedule, depth, service, value_refs) VALUES (31, 'define', 'billing', 'tasks', NULL, NULL, NULL, 'alice', 1791536400000, '{"hash":"88b49e1bb9dd9a410d173f997551da6295d3fcc54c4e182df558f2d7e96282f6"}', NULL, NULL, NULL, 0, NULL, NULL);
INSERT INTO engine_events (cursor, kind, namespace, schema, instance_id, seq, version, actor, at, change, cause_behavior, cause_event, cause_schedule, depth, service, value_refs) VALUES (32, 'publish', 'billing', 'tasks', NULL, NULL, 1, 'alice', 1791536400000, '{"description":"A task an engine runs with the core''s behaviors and no extension: it moves from todo through doing to done, waits for its blockers, a task or a document, before it is done, and links to the document it implements, pinned to a revision, to a parent task and to its project, which every create gives.","kind":"General","name":"tasks","types":{"Task":{"behaviors":[{"config":{"states":["todo","doing","done","dropped"],"transitions":[{"from":"todo","to":"doing"},{"from":"doing","to":"done"},{"from":"todo","to":"dropped"},{"from":"doing","to":"dropped"}]},"name":"Workflow"},{"config":{"gatedStates":["done"],"schemas":["tasks","documents"]},"name":"Dependencies"},{"config":{"links":{"parent":{"schema":"tasks"},"project":{"required":true,"schema":"projects"},"spec":{"pinned":true,"schema":"documents"}}},"name":"Links"}],"fields":[{"name":"title","required":true,"typeRef":{"name":"string"},"validateMaxLength":200}],"name":"Task","role":"EmbeddedStruct"}}}', NULL, NULL, NULL, 0, NULL, NULL);
INSERT INTO engine_events (cursor, kind, namespace, schema, instance_id, seq, version, actor, at, change, cause_behavior, cause_event, cause_schedule, depth, service, value_refs) VALUES (33, 'define', 'billing', 'projects', NULL, NULL, NULL, 'alice', 1791536400000, '{"hash":"afe736ff5af973fc5731eedf68d40082259e6638b8a5141afce662a6886637db"}', NULL, NULL, NULL, 0, NULL, NULL);
INSERT INTO engine_events (cursor, kind, namespace, schema, instance_id, seq, version, actor, at, change, cause_behavior, cause_event, cause_schedule, depth, service, value_refs) VALUES (34, 'publish', 'billing', 'projects', NULL, NULL, 1, 'alice', 1791536400000, '{"description":"A project an engine runs with the core''s behaviors and no extension: it moves from active to done or dropped, and rolls up the tasks that point at it through their project link: how many there are, how many are in each status, and whether every one is in a terminal state, which it needs before it is done.","kind":"General","name":"projects","types":{"Project":{"behaviors":[{"config":{"states":["active","done","dropped"],"transitions":[{"from":"active","to":"done"},{"from":"active","to":"dropped"}]},"name":"Workflow"},{"config":{"rollups":{"tasks":{"function":"count","link":"project","schema":"tasks"},"tasksByStatus":{"field":"Workflow.status","function":"countBy","link":"project","schema":"tasks"},"tasksFinished":{"function":"all","gatedStates":["done"],"link":"project","schema":"tasks"}}},"name":"Rollups"}],"fields":[{"name":"title","required":true,"typeRef":{"name":"string"},"validateMaxLength":200}],"name":"Project","role":"EmbeddedStruct"}}}', NULL, NULL, NULL, 0, NULL, NULL);
INSERT INTO engine_events (cursor, kind, namespace, schema, instance_id, seq, version, actor, at, change, cause_behavior, cause_event, cause_schedule, depth, service, value_refs) VALUES (35, 'define', 'billing', 'invoices', NULL, NULL, NULL, 'alice', 1791536400000, '{"hash":"31c3cc2505e02ac8254ee76f1cbccf53013b145f6053415ba0d9383236cec10f"}', NULL, NULL, NULL, 0, NULL, NULL);
INSERT INTO engine_events (cursor, kind, namespace, schema, instance_id, seq, version, actor, at, change, cause_behavior, cause_event, cause_schedule, depth, service, value_refs) VALUES (36, 'publish', 'billing', 'invoices', NULL, NULL, 1, 'alice', 1791536400000, '{"description":"An invoice an engine runs with the core''s behaviors and no extension: it bills the project every create gives, and is numbered at its create, INV-2026-0001 on, in a count of its project''s own that starts again each UTC year.","kind":"General","name":"invoices","types":{"Invoice":{"behaviors":[{"config":{"links":{"project":{"required":true,"schema":"projects"}}},"name":"Links"},{"config":{"format":"INV-{yyyy}-{seq:4}","reset":"yearly","scope":{"link":"project"}},"name":"Numbering"}],"fields":[{"name":"title","required":true,"typeRef":{"name":"string"},"validateMaxLength":200},{"name":"amount","typeRef":{"name":"number"}}],"name":"Invoice","role":"EmbeddedStruct"}}}', NULL, NULL, NULL, 0, NULL, NULL);
