CREATE TABLE engine_migrations (owner TEXT NOT NULL, version INTEGER NOT NULL, name TEXT NOT NULL, applied_at INTEGER NOT NULL, PRIMARY KEY (owner, version)) STRICT;
CREATE TABLE engine_schemas (namespace TEXT NOT NULL, name TEXT NOT NULL, version INTEGER NOT NULL CHECK (version >= 0), document TEXT NOT NULL CHECK (json_valid(document)), hash TEXT NOT NULL, defined_at INTEGER NOT NULL, published_at INTEGER, defined_by TEXT, published_by TEXT, published_cursor INTEGER, PRIMARY KEY (namespace, name, version), CHECK ((version = 0) = (published_at IS NULL))) STRICT;
CREATE INDEX engine_schemas_name ON engine_schemas (name, namespace);
CREATE TABLE engine_instances (position INTEGER PRIMARY KEY AUTOINCREMENT, namespace TEXT NOT NULL, schema TEXT NOT NULL, id TEXT NOT NULL, schema_namespace TEXT NOT NULL, version INTEGER NOT NULL CHECK (version >= 1), seq INTEGER NOT NULL CHECK (seq >= 1), data TEXT NOT NULL CHECK (json_valid(data) AND json_type(data) = 'object'), created_at INTEGER NOT NULL, created_by TEXT NOT NULL, updated_at INTEGER NOT NULL, updated_by TEXT NOT NULL, value_refs TEXT CHECK (value_refs IS NULL OR json_valid(value_refs)), "bhv_workflow__status" TEXT, "bhv_workflow__entered_at" INTEGER, "bhv_comments__count" INTEGER NOT NULL DEFAULT 0, "bhv_revisions__current" INTEGER NOT NULL DEFAULT 0, "bhv_lease__holder" TEXT, "bhv_lease__token" INTEGER NOT NULL DEFAULT 0, "bhv_lease__acquired_at" INTEGER, "bhv_lease__expires_at" INTEGER, "bhv_lease__ttl_ms" INTEGER, "bhv_lease__expiries" INTEGER NOT NULL DEFAULT 0, "bhv_lease__ended_reason" TEXT, "bhv_lease__ended_at" INTEGER, "bhv_lease__renewed_at" INTEGER, "bhv_assignment__assignee" TEXT, "bhv_assignment__assigned_at" INTEGER, "bhv_assignment__assigned_by" TEXT, "bhv_queue__status" TEXT, "bhv_queue__blocked" INTEGER NOT NULL DEFAULT 0, "bhv_queue__assignee" TEXT, "bhv_queue__expiries" INTEGER NOT NULL DEFAULT 0, "bhv_queue__priority" INTEGER, "bhv_queue__excluded_until" INTEGER NOT NULL DEFAULT 0, "bhv_retries__total" INTEGER NOT NULL DEFAULT 0, "bhv_retries__exhausted" INTEGER NOT NULL DEFAULT 0, "bhv_retries__stuck" INTEGER NOT NULL DEFAULT 0, "bhv_retries__streak" INTEGER NOT NULL DEFAULT 0, "bhv_retries__last_signature" TEXT, "bhv_retries__best_score" REAL, "bhv_retries__attempts" INTEGER NOT NULL DEFAULT 0, "bhv_presence__deadline" INTEGER, "bhv_presence__last_beat_at" INTEGER, "bhv_presence__missed" INTEGER NOT NULL DEFAULT 0, "bhv_presence__released" TEXT, "bhv_blueprint__stamped_at" INTEGER, "bhv_numbering__number" INTEGER, "bhv_numbering__label" TEXT, UNIQUE (namespace, schema, id)) STRICT;
CREATE INDEX engine_instances_list ON engine_instances (namespace, schema, position);
CREATE TABLE engine_behaviors (name TEXT PRIMARY KEY, key TEXT NOT NULL UNIQUE, created_at INTEGER NOT NULL) STRICT;
CREATE TABLE engine_references (namespace TEXT NOT NULL, target_schema TEXT NOT NULL, target_id TEXT NOT NULL, source_schema TEXT NOT NULL, source_id TEXT NOT NULL, behavior TEXT NOT NULL, key TEXT NOT NULL, hears TEXT, crosses REAL, PRIMARY KEY (namespace, target_schema, target_id, source_schema, source_id, behavior, key)) STRICT;
CREATE INDEX engine_references_source ON engine_references (namespace, source_schema, source_id, behavior);
CREATE TABLE engine_subscriptions (behavior TEXT NOT NULL, namespace TEXT NOT NULL, schema TEXT NOT NULL, cursor INTEGER NOT NULL CHECK (cursor >= 0), halted INTEGER NOT NULL DEFAULT 0 CHECK (halted IN (0, 1)), attempts INTEGER NOT NULL DEFAULT 0 CHECK (attempts >= 0), retry_at INTEGER, failed_cursor INTEGER, failed_at INTEGER, error TEXT, skipped INTEGER NOT NULL DEFAULT 0 CHECK (skipped >= 0), skipped_cursor INTEGER, skipped_reason TEXT CHECK (skipped_reason IS NULL OR skipped_reason IN ('depth', 'resume')), PRIMARY KEY (behavior, namespace, schema)) STRICT;
CREATE TABLE engine_schedules (behavior TEXT NOT NULL, schedule TEXT NOT NULL, namespace TEXT NOT NULL, schema TEXT NOT NULL, last_run_at INTEGER, next_run_at INTEGER NOT NULL, failures INTEGER NOT NULL DEFAULT 0 CHECK (failures >= 0), error TEXT, PRIMARY KEY (behavior, schedule, namespace, schema)) STRICT;
CREATE TABLE "engine_events" (cursor INTEGER PRIMARY KEY AUTOINCREMENT, kind TEXT NOT NULL CHECK (kind IN ('create', 'update', 'delete', 'operation', 'publish', 'define')), namespace TEXT NOT NULL, schema TEXT NOT NULL, instance_id TEXT, seq INTEGER CHECK (seq >= 1), version INTEGER CHECK (version >= 1), actor TEXT NOT NULL, at INTEGER NOT NULL, change TEXT CHECK (change IS NULL OR json_valid(change)), cause_behavior TEXT, cause_event INTEGER, cause_schedule TEXT, depth INTEGER NOT NULL DEFAULT 0 CHECK (depth >= 0), service TEXT, value_refs TEXT CHECK (value_refs IS NULL OR json_valid(value_refs)), CHECK ((kind IN ('publish', 'define')) = (instance_id IS NULL)), CHECK ((instance_id IS NULL) = (seq IS NULL)), CHECK ((kind = 'define') = (version IS NULL))) STRICT;
CREATE UNIQUE INDEX engine_events_instance ON engine_events (namespace, schema, instance_id, seq) WHERE instance_id IS NOT NULL;
CREATE INDEX engine_events_namespace ON engine_events (namespace, cursor);
CREATE INDEX engine_events_schema ON engine_events (namespace, schema, cursor);
CREATE INDEX engine_events_publish ON engine_events (namespace, cursor) WHERE kind = 'publish';
CREATE INDEX engine_references_hears ON engine_references (namespace, target_schema, target_id, hears, crosses);
CREATE TABLE engine_payloads (hash TEXT PRIMARY KEY, value TEXT NOT NULL CHECK (json_valid(value)), bytes INTEGER NOT NULL CHECK (bytes >= 0)) STRICT;
CREATE TABLE engine_payload_holders (hash TEXT NOT NULL, namespace TEXT NOT NULL, schema TEXT NOT NULL, holder TEXT NOT NULL, id TEXT NOT NULL, key TEXT NOT NULL, PRIMARY KEY (hash, namespace, schema, holder, id, key)) STRICT;
CREATE INDEX engine_payload_holders_holder ON engine_payload_holders (namespace, schema, holder, id, key);
CREATE TABLE engine_namespaces (name TEXT PRIMARY KEY, created_at INTEGER NOT NULL, created_by TEXT NOT NULL, archived_at INTEGER, archived_by TEXT, CHECK ((archived_at IS NULL) = (archived_by IS NULL))) STRICT;
CREATE TABLE engine_log_floors (namespace TEXT PRIMARY KEY, floor INTEGER NOT NULL CHECK (floor >= 0), publish_floor INTEGER NOT NULL DEFAULT 0 CHECK (publish_floor >= 0), pruned INTEGER NOT NULL DEFAULT 0 CHECK (pruned >= 0)) STRICT;
CREATE TABLE engine_event_bases (namespace TEXT NOT NULL, schema TEXT NOT NULL, instance_id TEXT NOT NULL, seq INTEGER NOT NULL CHECK (seq >= 1), data TEXT CHECK (data IS NULL OR (json_valid(data) AND json_type(data) = 'object')), value_refs TEXT CHECK (value_refs IS NULL OR json_valid(value_refs)), PRIMARY KEY (namespace, schema, instance_id)) STRICT;
CREATE INDEX "bhv_workflow___index_status" ON engine_instances (namespace, schema, "bhv_workflow__status");
CREATE TABLE bhv_comments__comments (namespace TEXT NOT NULL, schema TEXT NOT NULL, id TEXT NOT NULL, comment INTEGER NOT NULL, reply_to INTEGER, body TEXT NOT NULL, created_by TEXT NOT NULL, created_at INTEGER NOT NULL, PRIMARY KEY (namespace, schema, id, comment)) STRICT;
CREATE TABLE bhv_revisions__revisions (namespace TEXT NOT NULL, schema TEXT NOT NULL, id TEXT NOT NULL, revision INTEGER NOT NULL, data TEXT NOT NULL CHECK (json_valid(data)), created_by TEXT NOT NULL, created_at INTEGER NOT NULL, proposal INTEGER, value_refs TEXT, PRIMARY KEY (namespace, schema, id, revision)) STRICT;
CREATE TABLE bhv_revisions__proposals (namespace TEXT NOT NULL, schema TEXT NOT NULL, id TEXT NOT NULL, proposal INTEGER NOT NULL, patch TEXT NOT NULL CHECK (json_valid(patch)), note TEXT, base INTEGER, state TEXT NOT NULL CHECK (state IN ('pending', 'approved', 'rejected')), created_by TEXT NOT NULL, created_at INTEGER NOT NULL, reviewed_by TEXT, reviewed_at INTEGER, reason TEXT, revision INTEGER, value_refs TEXT, evidence TEXT, PRIMARY KEY (namespace, schema, id, proposal)) STRICT;
CREATE INDEX bhv_revisions__proposals_by_state ON bhv_revisions__proposals (namespace, schema, id, state, proposal);
CREATE TABLE bhv_dependencies__edges (edge INTEGER PRIMARY KEY, namespace TEXT NOT NULL, schema TEXT NOT NULL, id TEXT NOT NULL, blocker_schema TEXT NOT NULL, blocker_id TEXT NOT NULL, created_by TEXT NOT NULL, created_at INTEGER NOT NULL, UNIQUE (namespace, schema, id, blocker_schema, blocker_id)) STRICT;
CREATE INDEX bhv_dependencies__edges_by_blocker ON bhv_dependencies__edges (namespace, blocker_schema, blocker_id, edge);
CREATE TABLE "bhv_links__links" (row INTEGER PRIMARY KEY, namespace TEXT NOT NULL, schema TEXT NOT NULL, id TEXT NOT NULL, name TEXT NOT NULL, target_schema TEXT NOT NULL, target_id TEXT NOT NULL, revision INTEGER, release INTEGER, created_by TEXT NOT NULL, created_at INTEGER NOT NULL, UNIQUE (namespace, schema, id, name, target_schema, target_id)) STRICT;
CREATE INDEX bhv_links__links_by_target ON bhv_links__links (namespace, schema, name, target_id, row);
CREATE TABLE bhv_search__rows (row INTEGER PRIMARY KEY, namespace TEXT NOT NULL, schema TEXT NOT NULL, id TEXT NOT NULL, source_hash TEXT, vector BLOB, settled_at INTEGER, settled_by TEXT, UNIQUE (namespace, schema, id)) STRICT;
CREATE VIRTUAL TABLE bhv_search__text USING fts5(f1, f2, f3, f4, f5, f6, f7, f8, f9, f10, f11, f12, f13, f14, f15, f16, tokenize = 'unicode61 remove_diacritics 2');
CREATE INDEX bhv_search__rows_stale ON bhv_search__rows (namespace, schema, row) WHERE source_hash IS NOT NULL AND vector IS NULL;
CREATE INDEX bhv_search__rows_embedded ON bhv_search__rows (namespace, schema, row) WHERE vector IS NOT NULL;
CREATE TABLE "bhv_branches__ref" (id TEXT NOT NULL PRIMARY KEY, graph TEXT NOT NULL, root_id TEXT NOT NULL, parent_ref_id TEXT REFERENCES "bhv_branches__ref" (id), base_commit_id TEXT REFERENCES "bhv_branches__commit" (id), head_commit_id TEXT REFERENCES "bhv_branches__commit" (id), name TEXT NOT NULL, sealed_at INTEGER, created_at INTEGER NOT NULL, created_by TEXT NOT NULL, updated_at INTEGER NOT NULL, updated_by TEXT NOT NULL, deleted_at INTEGER, deleted_by TEXT, _version INTEGER NOT NULL) STRICT;
CREATE UNIQUE INDEX "bhv_branches__ref_live_name" ON "bhv_branches__ref" (graph, root_id, name) WHERE deleted_at IS NULL;
CREATE TABLE "bhv_branches__ref_history" (history_id TEXT NOT NULL PRIMARY KEY, graph TEXT NOT NULL, id TEXT NOT NULL, _version INTEGER NOT NULL, operation TEXT NOT NULL CHECK (operation IN ('INSERT', 'UPDATE', 'DELETE')), data TEXT NOT NULL, recorded_at INTEGER NOT NULL) STRICT;
CREATE UNIQUE INDEX "bhv_branches__ref_history_version" ON "bhv_branches__ref_history" (id, _version);
CREATE TABLE "bhv_branches__commit" (id TEXT NOT NULL PRIMARY KEY, graph TEXT NOT NULL, root_id TEXT NOT NULL, ref_id TEXT NOT NULL REFERENCES "bhv_branches__ref" (id), parent_commit_id TEXT REFERENCES "bhv_branches__commit" (id), message TEXT, schema_epoch INTEGER NOT NULL, content_hash TEXT NOT NULL, sequence INTEGER, created_at INTEGER NOT NULL, created_by TEXT NOT NULL) STRICT;
CREATE UNIQUE INDEX "bhv_branches__commit_sequence" ON "bhv_branches__commit" (graph, root_id, sequence);
CREATE TABLE "bhv_branches__patch" (id TEXT NOT NULL PRIMARY KEY, graph TEXT NOT NULL, commit_id TEXT NOT NULL REFERENCES "bhv_branches__commit" (id), entity_kind TEXT NOT NULL, entity_key TEXT NOT NULL, entity_id TEXT NOT NULL, entity_version INTEGER NOT NULL, operation TEXT NOT NULL CHECK (operation IN ('ADD', 'UPDATE', 'DELETE'))) STRICT;
CREATE UNIQUE INDEX "bhv_branches__patch_entity" ON "bhv_branches__patch" (commit_id, entity_kind, entity_key);
CREATE INDEX "bhv_branches__patch_pin" ON "bhv_branches__patch" (entity_id, entity_version);
CREATE TABLE "bhv_branches__snapshot_entry" (id TEXT NOT NULL PRIMARY KEY, graph TEXT NOT NULL, commit_id TEXT NOT NULL REFERENCES "bhv_branches__commit" (id), entity_kind TEXT NOT NULL, entity_key TEXT NOT NULL, entity_id TEXT NOT NULL, entity_version INTEGER NOT NULL) STRICT;
CREATE UNIQUE INDEX "bhv_branches__snapshot_entry_entity" ON "bhv_branches__snapshot_entry" (commit_id, entity_kind, entity_key);
CREATE INDEX "bhv_branches__snapshot_entry_pin" ON "bhv_branches__snapshot_entry" (entity_id, entity_version);
CREATE TABLE "bhv_branches__release" (id TEXT NOT NULL PRIMARY KEY, graph TEXT NOT NULL, root_id TEXT NOT NULL, commit_id TEXT NOT NULL REFERENCES "bhv_branches__commit" (id), created_at INTEGER NOT NULL, created_by TEXT NOT NULL, updated_at INTEGER NOT NULL, updated_by TEXT NOT NULL, _version INTEGER NOT NULL) STRICT;
CREATE UNIQUE INDEX "bhv_branches__release_root" ON "bhv_branches__release" (graph, root_id);
CREATE TABLE "bhv_branches__release_history" (history_id TEXT NOT NULL PRIMARY KEY, graph TEXT NOT NULL, id TEXT NOT NULL, _version INTEGER NOT NULL, operation TEXT NOT NULL CHECK (operation IN ('INSERT', 'UPDATE', 'DELETE')), data TEXT NOT NULL, recorded_at INTEGER NOT NULL) STRICT;
CREATE UNIQUE INDEX "bhv_branches__release_history_version" ON "bhv_branches__release_history" (id, _version);
CREATE TABLE "bhv_branches__member" (id TEXT NOT NULL PRIMARY KEY, graph TEXT NOT NULL, kind TEXT NOT NULL, entity_key TEXT NOT NULL, ref_id TEXT NOT NULL REFERENCES "bhv_branches__ref" (id), root_id TEXT NOT NULL, tombstone INTEGER NOT NULL CHECK (tombstone IN (0, 1)), _version INTEGER NOT NULL, data TEXT NOT NULL) STRICT;
CREATE UNIQUE INDEX "bhv_branches__member_entity" ON "bhv_branches__member" (graph, kind, ref_id, entity_key);
CREATE TABLE "bhv_branches__member_history" (history_id TEXT NOT NULL PRIMARY KEY, graph TEXT NOT NULL, kind TEXT NOT NULL, id TEXT NOT NULL, _version INTEGER NOT NULL, operation TEXT NOT NULL CHECK (operation IN ('INSERT', 'UPDATE', 'DELETE')), data TEXT NOT NULL, recorded_at INTEGER NOT NULL) STRICT;
CREATE UNIQUE INDEX "bhv_branches__member_history_version" ON "bhv_branches__member_history" (id, _version);
CREATE INDEX "bhv_branches__member_history_recorded" ON "bhv_branches__member_history" (graph, kind, recorded_at);
CREATE TABLE bhv_branches__roots (graph TEXT NOT NULL, root_id TEXT NOT NULL, id TEXT NOT NULL, PRIMARY KEY (graph, root_id)) STRICT;
CREATE TABLE bhv_branches__actors (actor TEXT NOT NULL PRIMARY KEY, subject TEXT NOT NULL) STRICT;
CREATE TABLE bhv_approvals__signoffs (signoff INTEGER PRIMARY KEY, namespace TEXT NOT NULL, schema TEXT NOT NULL, id TEXT NOT NULL, state TEXT NOT NULL, subject TEXT NOT NULL, note TEXT, at INTEGER NOT NULL, consumed_at INTEGER) STRICT;
CREATE UNIQUE INDEX bhv_approvals__signoffs_live ON bhv_approvals__signoffs (namespace, schema, id, state, subject) WHERE consumed_at IS NULL;
CREATE INDEX bhv_approvals__signoffs_by_instance ON bhv_approvals__signoffs (namespace, schema, id, signoff);
CREATE TABLE bhv_timers__deadlines (namespace TEXT NOT NULL, schema TEXT NOT NULL, id TEXT NOT NULL, name TEXT NOT NULL, base_at INTEGER, armed_from TEXT, due_at INTEGER, fired INTEGER NOT NULL DEFAULT 0, fired_at INTEGER, outcome TEXT, PRIMARY KEY (namespace, schema, id, name)) STRICT;
CREATE INDEX bhv_timers__deadlines_due ON bhv_timers__deadlines (namespace, schema, due_at, id, name) WHERE fired = 0;
CREATE INDEX "bhv_lease___index_held" ON engine_instances (namespace, schema, "bhv_lease__holder", "bhv_lease__expires_at");
CREATE TABLE bhv_lease__directives (namespace TEXT NOT NULL, schema TEXT NOT NULL, id TEXT NOT NULL, token INTEGER NOT NULL, directive INTEGER NOT NULL, name TEXT NOT NULL, data TEXT, created_by TEXT NOT NULL, created_at INTEGER NOT NULL, acknowledged_at INTEGER, dedupe_key TEXT, PRIMARY KEY (namespace, schema, id, token, directive)) STRICT;
CREATE INDEX "bhv_lease___index_holder" ON engine_instances (namespace, schema, "bhv_lease__holder");
CREATE INDEX "bhv_assignment___index_assignee" ON engine_instances (namespace, schema, "bhv_assignment__assignee");
CREATE INDEX "bhv_queue___index_claimable" ON engine_instances (namespace, schema, "bhv_queue__status", "bhv_queue__blocked", "bhv_queue__priority");
CREATE INDEX "bhv_queue___index_eligible" ON engine_instances (namespace, schema, "bhv_queue__status", "bhv_queue__blocked", "bhv_queue__excluded_until");
CREATE TABLE bhv_budget__meters (namespace TEXT NOT NULL, schema TEXT NOT NULL, id TEXT NOT NULL, meter TEXT NOT NULL, used INTEGER NOT NULL DEFAULT 0, reserved INTEGER NOT NULL DEFAULT 0, limit_value INTEGER, period_start INTEGER, reservation INTEGER NOT NULL DEFAULT 0, token INTEGER, directed INTEGER, scope_schema TEXT, scope_id TEXT, PRIMARY KEY (namespace, schema, id, meter)) STRICT;
CREATE TABLE bhv_budget__holds (namespace TEXT NOT NULL, schema TEXT NOT NULL, id TEXT NOT NULL, meter TEXT NOT NULL, inner_schema TEXT NOT NULL, inner_id TEXT NOT NULL, amount INTEGER NOT NULL, PRIMARY KEY (namespace, schema, id, meter, inner_schema, inner_id)) STRICT;
CREATE TABLE bhv_retries__classes (namespace TEXT NOT NULL, schema TEXT NOT NULL, id TEXT NOT NULL, class TEXT NOT NULL, attempts INTEGER NOT NULL, PRIMARY KEY (namespace, schema, id, class)) STRICT;
CREATE TABLE bhv_retries__attempts (namespace TEXT NOT NULL, schema TEXT NOT NULL, id TEXT NOT NULL, attempt INTEGER NOT NULL, failure TEXT, score REAL, kept INTEGER NOT NULL, signature TEXT, predicates TEXT, created_by TEXT NOT NULL, created_at INTEGER NOT NULL, PRIMARY KEY (namespace, schema, id, attempt)) STRICT;
CREATE INDEX "bhv_retries___index_exhausted" ON engine_instances (namespace, schema, "bhv_retries__exhausted");
CREATE INDEX "bhv_presence___index_due" ON engine_instances (namespace, schema, "bhv_presence__missed", "bhv_presence__deadline");
CREATE TABLE bhv_blueprint__children (namespace TEXT NOT NULL, schema TEXT NOT NULL, id TEXT NOT NULL, position INTEGER NOT NULL, step TEXT NOT NULL, child_id TEXT NOT NULL, PRIMARY KEY (namespace, schema, id, position)) STRICT;
CREATE INDEX "bhv_numbering___index_number" ON engine_instances (namespace, schema, "bhv_numbering__number");
CREATE INDEX "bhv_numbering___index_label" ON engine_instances (namespace, schema, "bhv_numbering__label");
CREATE TABLE bhv_numbering__counters (namespace TEXT NOT NULL, schema TEXT NOT NULL, scope_key TEXT NOT NULL, last INTEGER NOT NULL, PRIMARY KEY (namespace, schema, scope_key)) STRICT;
CREATE TABLE bhv_numbering__labels (namespace TEXT NOT NULL, schema TEXT NOT NULL, id TEXT NOT NULL, scope_key TEXT NOT NULL, label TEXT NOT NULL, PRIMARY KEY (namespace, schema, id), UNIQUE (namespace, schema, scope_key, label)) STRICT;
DELETE FROM sqlite_sequence;
CREATE TRIGGER engine_events_no_update BEFORE UPDATE ON engine_events BEGIN SELECT RAISE(ABORT, 'engine_events is append-only'); END;
CREATE TRIGGER engine_events_no_delete BEFORE DELETE ON engine_events WHEN OLD.cursor > COALESCE((SELECT floor FROM engine_log_floors WHERE namespace = OLD.namespace), 0) BEGIN SELECT RAISE(ABORT, 'engine_events is append-only'); END;
